[Form]
public class METSalesOrderFinalizationFilterDialog extends FormRun
{
    FormRun             callerFormObject;
    FormDataSource      metSalesOrderShipmentHeaderDS;
    TransDate           fromShipDate;
    TransDate           toShipDate;
    CustAccount         custAccountStr;
    InventLocationId    fromWarehouse;
    InventLocationId    toWarehouseStr;
    MetShipmentStatus   metShipmentStatus;
    METRoute            routeStr;
    METOrderTransactionType orderTransactionType;
    METInventLocationIdToTmp tableBuffer;

    #define.CurrentVersion(2)

    #localmacro.CurrentList
        fromShipDate,
        toShipDate,
        fromWarehouse,
        toWarehouseStr,
        custAccountStr,
        metShipmentStatus,
        routeStr
    #endmacro

}

/// <summary>
/// Form init method
/// </summary>
public void init()
{
    super();

    orderTransactionType = element.args().parmEnum();

    if (orderTransactionType ==METOrderTransactionType::TransferOrder)
    {
        Warehouse.label("@MET:FromWH");
        ToWarehouse.label("@MET:ToWH");
        CustAccount.visible(false);
    }
    else
    {
        ToWarehouse.visible(false);
    }

    tableBuffer.populateInventLocationTemp(tableBuffer);
}

/// <summary>
/// Last value user Id reference
/// </summary>
/// <returns>UserId</returns>
private UserId lastValueUserId()
{
    return curUserId();
}

/// <summary>
/// Last value type method of form
/// </summary>
/// <returns>UtilElementType</returns>
private UtilElementType lastValueType()
{
    return UtilElementType::Form;
}

/// <summary>
/// Last value element name
/// </summary>
/// <returns>IdentifierName</returns>
private IdentifierName lastValueElementName()
{
    return this.name();
}

/// <summary>
/// Last design value name
/// </summary>
/// <returns>IdentifierName</returns>
private IdentifierName lastValueDesignName()
{
    return '';
}

/// <summary>
/// Last data areaId value
/// </summary>
/// <returns>Data area Id</returns>
DataAreaId lastValueDataAreaId()
{
    return curExt();
}

/// <summary>
/// Pack method to pack the controls
/// </summary>
/// <returns>Container reference</returns>
public container pack()
{
    this.getControlValuesForSysLastValues();
    return [#CurrentVersion, #CurrentList];
}

/// <summary>
/// Unpack method to unpack the current version
/// </summary>
/// <param name = "packedClass">Container reference</param>
/// <returns>Boolean</returns>
public boolean unpack(container packedClass)
{
    Integer version = conPeek(packedClass, 1);
    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList] = packedClass;
            break;
        default:
            return false;
    }
    return true;
}

/// <summary>
/// Close method of form
/// </summary>
public void close()
{
    xSysLastValue::saveLast(this);
    super();
}

/// <summary>
/// Run method of form
/// </summary>
public void run()
{
    super();
    xSysLastValue::getLast(this);
    this.setControlValuesFromSysLastValues();
}

/// <summary>
/// getting values back to controls
/// </summary>
void getControlValuesForSysLastValues()
{
    fromShipDate = ShipFromDate.dateValue();
    toShipDate = ShipToDate.dateValue();
    fromWarehouse = Warehouse.text();
    toWarehouseStr = ToWarehouse.text();
    custAccountStr = CustAccount.text();
    metShipmentStatus = ShipmentStatus.selection();
    routeStr    = Route.text();

}

/// <summary>
/// Setting values back to controls
/// </summary>
void setControlValuesFromSysLastValues()
{
    TransDate       today = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

    ShipFromDate.dateValue(fromShipDate);
    ShipToDate.dateValue(toShipDate);
    route.text(routeStr);
    Warehouse.text(fromWarehouse);
    if (orderTransactionType == METOrderTransactionType::TransferOrder)
    {
        ToWarehouse.text(toWarehouseStr);
    }
    else
    {
        CustAccount.text(custAccountStr);
    }

    ShipmentStatus.selection(MetShipmentStatus::Open);


    if (ShipFromDate.dateValue() == dateNull())
    {
        ShipFromDate.dateValue(today);
    }

    if (ShipToDate.dateValue() == dateNull())
    {
        ShipToDate.dateValue(today);
    }

}

/// <summary>
/// Warehouse modified method to validate restricted access for finalization
/// </summary>
/// <returns>boolean</returns>
public boolean modified()
{
    boolean ret;
    InventLocationId warehouseId = this.valueStr();

    ret = super();

    if (warehouseId && !Global::isSystemAdministrator())
    {
        METUserSecurityGroupList        securityGroupList;
        METUserSecurityWarehouseList    warehouseList;

        select firstonly RecId from warehouseList
            where warehouseList.InventLocationId == warehouseId
               && warehouseList.Company == curExt()
               && warehouseList.RestrictSOFinalization == NoYes::Yes
            exists join securityGroupList
                where securityGroupList.UserSecurityGroupId == warehouseList.UserSecurityGroupId
                   && securityGroupList.UserId == curUserId();

        if (warehouseList.RecId)
        {
            warning(strFmt("@MET:WarehouseSOFinalizationRestricted", warehouseId));
            this.text('');
            return false;
        }
    }

    return ret;
}

/// <summary>
/// Provides a lookup for InventLocation values using the temporary table
/// METInventLocationIdToTmp. The temp table holds InventLocationId, Name,
/// and InventSiteId temporarily for lookup display. The lookup uses the
/// same in‑memory buffer instance supplied through parmTmpBuffer().
/// </summary>
public void lookup()
{
    METInventLocationIdToTmp tmpBuffer = tableBuffer;
    tmpBuffer.lookup(this);
}

/// <summary>
/// Clicked method for the control
/// </summary>
public void clicked()
{
    boolean                     isOpenShipment = ShipmentStatus.selection() == enum2int(MetShipmentStatus::Open);
    boolean                     isShippedShipment = ShipmentStatus.selection() == enum2int(MetShipmentStatus::Shipped);  // CB272 - LaserNet Reprint
    QueryBuildDataSource        lineQbds;

    callerFormObject = element.args().caller();
    metSalesOrderShipmentHeaderDS = callerFormObject.dataSource(formDataSourceStr(METSalesOrderFinalizationWorkbench, METSalesOrderShipmentLoadHeader)) as FormDataSource;

    callerFormObject.design().controlName(formControlStr(METSalesOrderFinalizationWorkbench, METShipmentUpdateRoutesDialog)).enabled(isOpenShipment);
    callerFormObject.design().controlName(formControlStr(METSalesOrderFinalizationWorkbench, METShipmentUpdateRoutesLineDialog)).enabled(isOpenShipment);
    callerFormObject.design().controlName(formControlStr(METSalesOrderFinalizationWorkbench, HeaderGrid_PostMultiDocument)).enabled(isOpenShipment);
    callerFormObject.design().controlName(formControlStr(METSalesOrderFinalizationWorkbench, METSalesOrderShipmentConfirmationController)).enabled(!isShippedShipment);
    callerFormObject.design().controlName(formControlStr(METSalesOrderFinalizationWorkbench, METShipmentBundleReprintController)).enabled(isShippedShipment); // CB272 - LaserNet Reprint

    if (shipfromDate.dateValue() == dateNull() || ShipToDate.dateValue() == dateNull())
    {
        throw error("@MET:ShipDateMandatory");
    }

    if (shipfromDate.dateValue() > ShipToDate.dateValue())
    {
        throw error("@MET:ShipFromDateValidation");
    }

    if (Warehouse.valueStr() == '')
    {
        throw error("@MET:WHMandatory");
    }

    metSalesOrderShipmentHeaderDS.queryBuildDataSource().clearRanges();

    SysQuery::findOrCreateRange(metSalesOrderShipmentHeaderDS.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, TransactionType)).value(queryValue(orderTransactionType));

    if (Warehouse.text())
    {
        QueryBuildRange qbr;
        qbr = SysQuery::findOrCreateRange(metSalesOrderShipmentHeaderDS.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, Warehouse));
        qbr.value(queryValue(Warehouse.text()));
        qbr.status(RangeStatus::Locked);
    }

    if (Route.text())
    {
        QueryBuildRange qbr;
        qbr = SysQuery::findOrCreateRange(metSalesOrderShipmentHeaderDS.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, Route));
        qbr.value(queryValue(Route.text()));
        qbr.status(RangeStatus::Locked);
    }

    if (CustAccount.text())
    {
        QueryBuildRange qbr;
        qbr = SysQuery::findOrCreateRange(metSalesOrderShipmentHeaderDS.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, CustAccount));
        qbr.value(queryValue(CustAccount.text()));
        qbr.status(RangeStatus::Locked);
    }

    if (ToWarehouse.text())
    {
        QueryBuildRange qbr;
        qbr = SysQuery::findOrCreateRange(metSalesOrderShipmentHeaderDS.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, ToWarehouse));
        qbr.value(queryValue(ToWarehouse.text()));
        qbr.status(RangeStatus::Locked);
    }

    QueryBuildRange      dateRange;
    dateRange = SysQuery::findOrCreateRange(metSalesOrderShipmentHeaderDS.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, ConfirmedShipDate));
    daterange.value(SysQuery::range(ShipFromDate.dateValue(), ShipToDate.dateValue()));
    dateRange.status(RangeStatus::Locked);

    QueryBuildRange shipmentRange;
    shipmentRange = SysQuery::findOrCreateRange(metSalesOrderShipmentHeaderDS.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, ShipmentStatus));
    shipmentRange.value(queryValue(ShipmentStatus.selection()));
    shipmentRange.status(RangeStatus::Locked);


    lineQbds = metSalesOrderShipmentHeaderDS.queryBuildDataSource().addDataSource(tableNum(METSalesOrderShipmentLoadLines));
    lineQbds.relations(false);
    lineQbds.addLink(fieldNum(METSalesOrderShipmentLoadHeader, ShipmentId), fieldNum(METSalesOrderShipmentLoadLines, ShipmentId));
    lineQbds.joinMode(JoinMode::ExistsJoin);

    if (!callerFormObject.isFormInitialized())
    {
        callerFormObject.resetOnDialogApplyFilter();
    }

    metSalesOrderShipmentHeaderDS.executeQuery();
    metSalesOrderShipmentHeaderDS.research(true);

    super();
}
